import { Scene, Tex, Text, TransformMatchingTex, Rate, Color } from "retiam";

const scene = new Scene({ canvas });

// 1. Initial algebraic formula
const step1 = new Tex("(x + 1)^2 = 0", { fontSize: 40, fill: Color.WHITE });
scene.add(step1);

await scene.wait(1000);

// 2. Expanded algebraic formula
const step2 = new Tex("x^2 + 2x + 1 = 0", { fontSize: 40, fill: Color.WHITE });

// 3. Smooth symbol-matching formula transition
await scene.play(new TransformMatchingTex(step1, step2, {
    duration: 1500,
    rate_func: Rate.easeInOutCubic(),
    morphUnmatched: true
}));
